def _compute_validate_button_style(self):
    for picking in self:
        if picking.state in ('done', 'cancel'):
            picking.validate_button_style = 'invisible'
        elif picking.state in ('waiting', 'assigned'):
            picking.validate_button_style = 'primary'
        else:
            picking.validate_button_style = 'secondary'

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def _log_activity_get_documents(self, orig_obj_changes, stream_field, stream, groupby_method=False):
    """ Generic method to log activity. To use with
    _log_activity method. It either log on uppermost
    ongoing documents or following documents. This method
    find all the documents and responsible for which a note
    has to be log. It also generate a rendering_context in
    order to render a specific note by documents containing
    only the information relative to the document it. For example
    we don't want to notify a picking on move that it doesn't
    contain.

    :param dict orig_obj_changes: contain a record as key and the
        change on this record as value.
        eg: {'move_id': (new product_uom_qty, old product_uom_qty)}
    :param str stream_field: It has to be a field of the
        records that are register in the key of 'orig_obj_changes'
        eg: 'move_dest_ids' if we use move as record (previous example)
            - 'UP' if we want to log on the upper most ongoing
            documents.
            - 'DOWN' if we want to log on following documents.
    :param str stream: ``'UP'`` or ``'DOWN'``
    :param groupby_method: Only need when
        stream is 'DOWN', it should group by tuple(object on
        which the activity is log, the responsible for this object)
    """
    if self.env.context.get('skip_activity'):
        return {}
    move_to_orig_object_rel = {co: ooc for ooc in orig_obj_changes for co in ooc[stream_field]}
    origin_objects = self.env[next(iter(orig_obj_changes.keys()))._name].concat(orig_obj_changes.keys())
    # The purpose here is to group each destination object by
    # (document to log, responsible) no matter the stream direction.
    # example:
    # {'(delivery_picking_1, admin)': stock.move(1, 2)
    #  '(delivery_picking_2, admin)': stock.move(3)}
    visited_documents = {}
    if stream == 'DOWN':
        if groupby_method:
            grouped_moves = groupby(origin_objects.mapped(stream_field), key=groupby_method)
        else:
            raise AssertionError('You have to define a groupby method and pass them as arguments.')
    elif stream == 'UP':
        # When using upstream document it is required to define
        # _get_upstream_documents_and_responsibles on
        # destination objects in order to ascend documents.
        grouped_moves = {}
        for visited_move in origin_objects.mapped(stream_field):
            for document, responsible, visited in visited_move._get_upstream_documents_and_responsibles(self.env[visited_move._name]):
                if grouped_moves.get((document, responsible)):
                    grouped_moves[(document, responsible)] |= visited_move
                    visited_documents[(document, responsible)] |= visited
                else:
                    grouped_moves[(document, responsible)] = visited_move
                    visited_documents[(document, responsible)] = visited
        grouped_moves = grouped_moves.items()
    else:
        raise AssertionError('Unknown stream.')

    documents = {}
    for (parent, responsible), moves in grouped_moves:
        if not parent:
            continue
        moves = self.env[moves[0]._name].concat(moves)
        # Get the note
        rendering_context = {move: (orig_object, orig_obj_changes[orig_object]) for move in moves for orig_object in move_to_orig_object_rel[move]}
        if visited_documents:
            documents[(parent, responsible)] = rendering_context, visited_documents.values()
        else:
            documents[(parent, responsible)] = rendering_context
    return documents

def __setup__(cls):
    cls.number.search_unaccented = False
    cls.reference.search_unaccented = False
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.update({
            Index(t, (Coalesce(t.reference, ''), Index.Similarity())),
            })
    cls._order = [
        ('effective_date', 'ASC NULLS LAST'),
        ('id', 'ASC'),
        ]

def order_effective_date(cls, tables):
    table, _ = tables[None]
    return [Coalesce(table.effective_date, table.planned_date)]

def get_delay(self, name):
    pool = Pool()
    Date = pool.get('ir.date')
    planned_date = self.origin_planned_date or self.planned_date
    if planned_date is not None:
        if self.effective_date:
            return self.effective_date - planned_date
        elif self.planned_date:
            return self.planned_date - planned_date
        else:
            with Transaction().set_context(company=self.company.id):
                today = Date.today()
            return today - planned_date

def copy(cls, shipments, default=None):
    default = default.copy() if default is not None else {}
    default.setdefault('number')
    default.setdefault('reference')
    return super().copy(shipments, default=default)

def on_modification(cls, mode, shipments, field_names=None):
    pool = Pool()
    Move = pool.get('stock.move')
    super().on_modification(mode, shipments, field_names=field_names)
    if (mode in {'create', 'write'}
            and (field_names is None or 'planned_date' in field_names)):
        cls._set_move_planned_date(shipments)
    elif mode == 'delete':
        if hasattr(cls, 'moves'):
            moves = [m for s in shipments for m in s.moves]
            Move.delete(moves)

def check_modification(cls, mode, shipments, values=None, external=False):
    super().check_modification(
        mode, shipments, values=values, external=external)
    if mode == 'delete':
        for shipment in shipments:
            if shipment.state not in {'cancelled', 'request', 'draft'}:
                raise AccessError(gettext(
                        'stock.msg_shipment_delete_cancel',
                        shipment=shipment.rec_name))

def assign_ignore(cls, shipments, moves=None):
    pool = Pool()
    Move = pool.get('stock.move')
    assign_moves = {
        m for s in shipments for m in s.assign_moves
        if m.assignation_required and m.state in {'staging', 'draft'}}
    if moves is None:
        moves = list(assign_moves)
    else:
        moves = [m for m in moves if m in assign_moves]
    Move.write(moves, {
            'quantity': 0,
            })
    with cls.bulk_func('assign', auto=False) as assign:
        for shipment in shipments:
            if all(
                    m.state not in {'staging', 'draft'}
                    for m in shipment.assign_moves
                    if m.assignation_required):
                assign.push(shipment)

def get_partially_assigned(self, name):
    return (self.state != 'assigned'
        and any(m.state == 'assigned' for m in self.assign_moves
            if m.assignation_required))

def search_partially_assigned(cls, name, clause):
    operators = {
        '=': 'where',
        '!=': 'not where',
        }
    reverse = {
        '=': '!=',
        '!=': '=',
        }
    if clause[1] in operators:
        if not clause[2]:
            operator = reverse[clause[1]]
        else:
            operator = clause[1]
        return [
            (cls._assign_moves_field, operators[operator], [
                    ('state', '=', 'assigned'),
                    ('assignation_required', '=', True),
                    ]),
            ('state', '=', 'waiting'),
            ]
    else:
        return []

def __setup__(cls):
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.update({
            Index(
                t,
                (t.state, Index.Equality(cardinality='low')),
                where=t.state.in_(['draft', 'received'])),
            })
    cls._order = [
        ('id', 'DESC'),
        ]
    cls._transitions |= set((
            ('draft', 'received'),
            ('received', 'done'),
            ('draft', 'cancelled'),
            ('received', 'cancelled'),
            ('cancelled', 'draft'),
            ('done', 'cancelled'),
            ))
    cls._buttons.update({
            'cancel': {
                'invisible': (
                    (Eval('state') == 'cancelled')
                    | ((Eval('state') == 'done')
                        & ~Id('stock',
                            'group_stock_cancellation').in_(
                            Eval('context', {}).get('groups', []))
                        & ~Eval('context', {}).get(
                            'administrator', False))),
                'depends': ['state'],
                },
            'draft': {
                'invisible': Eval('state') != 'cancelled',
                'depends': ['state'],
                },
            'receive': {
                'invisible': Eval('state') != 'draft',
                'depends': ['state'],
                },
            'do': {
                'invisible': Eval('state') != 'received',
                'depends': ['state'],
                },
            })
    cls.moves.domain = ['OR',
        cls.incoming_moves.domain,
        cls.inventory_moves.domain,
        ]

def order_effective_date(cls, tables):
    table, _ = tables[None]
    return [Coalesce(table.effective_date, table.planned_date)]

def on_change_warehouse(self):
    if self.warehouse:
        self.warehouse_input = self.warehouse.input_location
        self.warehouse_storage = self.warehouse.storage_location
    else:
        self.warehouse_input = self.warehouse_storage = None

def on_change_supplier(self):
    self.contact_address = None
    if self.supplier:
        self.contact_address = self.supplier.address_get()

def get_incoming_moves(self, name):
    if self.warehouse_input == self.warehouse_storage:
        moves = self.moves
    else:
        moves = filter(
            lambda m: m.to_location == self.warehouse_input, self.moves)
    return sort(moves, self.__class__.incoming_moves.order)

def set_incoming_moves(cls, shipments, name, value):
    if not value:
        return
    cls.write(shipments, {
            'moves': value,
            })

def get_inventory_moves(self, name):
    moves = filter(
        lambda m: m.from_location == self.warehouse_input, self.moves)
    return sort(moves, self.__class__.inventory_moves.order)

def set_inventory_moves(cls, shipments, name, value):
    if not value:
        return
    cls.write(shipments, {
            'moves': value,
            })

def _set_move_planned_date(cls, shipments):
    '''
    Set planned date of moves for the shipments
    '''
    Move = Pool().get('stock.move')
    to_write = []
    for shipment in shipments:
        dates = shipment._move_planned_date
        incoming_date, inventory_date = dates
        if incoming_date:
            incoming_moves_to_write = [
                m for m in shipment.incoming_moves
                if (m.state not in {'done', 'cancelled'})]
            if incoming_moves_to_write:
                to_write.extend(
                    (incoming_moves_to_write, {
                            'planned_date': incoming_date,
                            }))
        if inventory_date:
            inventory_moves_to_write = [
                m for m in shipment.inventory_moves
                if (m.state not in {'done', 'cancelled'})]
            if inventory_moves_to_write:
                to_write.extend(
                    (inventory_moves_to_write, {
                            'planned_date': inventory_date,
                            }))
    if to_write:
        Move.write(*to_write)

def get_origins(self, name):
    return ', '.join(set(filter(None,
                (m.origin_name for m in self.incoming_moves))))

def chat_language(self, audience='internal'):
    language = super().chat_language(audience=audience)
    if audience == 'public':
        language = self.supplier.lang.code if self.supplier.lang else None
    return language

def preprocess_values(cls, mode, values):
    pool = Pool()
    Configuration = pool.get('stock.configuration')
    values = super().preprocess_values(mode, values)
    if mode == 'create' and not values.get('number'):
        company_id = values.get('company', cls.default_company())
        if company_id is not None:
            configuration = Configuration(1)
            if sequence := configuration.get_multivalue(
                    'shipment_in_sequence', company=company_id):
                values['number'] = sequence.get()
    return values

def copy(cls, shipments, default=None):
    if default is None:
        default = {}
    else:
        default = default.copy()
    default.setdefault('moves.origin', None)
    default.setdefault('received_by', None)
    default.setdefault('done_by', None)
    return super().copy(shipments, default=default)

def create_inventory_moves(cls, shipments):
    for shipment in shipments:
        if shipment.warehouse_storage == shipment.warehouse_input:
            # Do not create inventory moves
            continue
        # Use moves instead of inventory_moves because save reset before
        # adding new records and as set_inventory_moves is just a proxy to
        # moves, it will reset also the incoming_moves
        moves = list(shipment.moves)
        for incoming_move in shipment.incoming_moves:
            move = shipment._get_inventory_move(incoming_move)
            if move:
                moves.append(move)
        shipment.moves = moves
    cls.save(shipments)

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments
            for m in s.incoming_moves + s.inventory_moves])

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.incoming_moves
            if m.state != 'staging'])
    Move.delete([m for s in shipments for m in s.inventory_moves
            if m.state in {'staging', 'draft', 'cancelled'}])

def receive(cls, shipments):
    Move = Pool().get('stock.move')
    with Move.bulk_func('do', auto=False) as do:
        for shipment in shipments:
            do.extend(shipment.incoming_moves)
    with Move.bulk_delete(auto=False) as delete:
        for shipment in shipments:
            for move in shipment.inventory_moves:
                if move.state in {'draft', 'cancelled'}:
                    delete.push(move)
    cls.create_inventory_moves(shipments)
    # Set received state to allow done transition
    cls.write(shipments, {'state': 'received'})
    with cls.bulk_func('do', auto=False) as do:
        for shipment in shipments:
            if shipment.warehouse_storage == shipment.warehouse_input:
                do.push(shipment)

def do(cls, shipments):
    pool = Pool()
    Move = pool.get('stock.move')
    Date = pool.get('ir.date')
    inventory_moves = []
    for shipment in shipments:
        if shipment.warehouse_storage != shipment.warehouse_input:
            shipment.check_quantity()
        inventory_moves.extend(shipment.inventory_moves)
    Move.do(inventory_moves)
    for company, c_shipments in groupby(
            shipments, key=lambda s: s.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        cls.write([s for s in c_shipments if not s.effective_date], {
                'effective_date': today,
                })

def on_change_supplier(self):
    if self.supplier:
        self.delivery_address = self.supplier.address_get('delivery')
        self.to_location = self.supplier.supplier_location

def _set_move_planned_date(cls, shipments):
    '''
    Set planned date of moves for the shipments
    '''
    Move = Pool().get('stock.move')
    to_write = []
    for shipment in shipments:
        moves = [m for m in shipment.moves
                if (m.state not in {'done', 'cancelled'}
                    and m.planned_date != shipment._move_planned_date)]
        if moves:
            to_write.extend((moves, {
                        'planned_date': shipment._move_planned_date,
                        }))
    if to_write:
        Move.write(*to_write)

def get_origins(self, name):
    return ', '.join(set(filter(None,
                (m.origin_name for m in self.moves))))

def chat_language(self, audience='internal'):
    language = super().chat_language(audience=audience)
    if audience == 'public':
        language = self.supplier.lang.code if self.supplier.lang else None
    return language

def copy(cls, shipments, default=None):
    if default is None:
        default = {}
    else:
        default = default.copy()
    default.setdefault('moves.origin', None)
    default.setdefault('assigned_by', None)
    default.setdefault('done_by', None)
    return super().copy(shipments, default=default)

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.moves
            if m.state != 'staging'])
    for shipment in shipments:
        Move.write([m for m in shipment.moves
                if m.state != 'done'], {
                'from_location': shipment.from_location.id,
                'to_location': shipment.to_location.id,
                'planned_date': shipment.planned_date,
                })

def assign(cls, shipments):
    Move = Pool().get('stock.move')
    Move.assign([m for s in shipments for m in s.assign_moves])

def do(cls, shipments):
    pool = Pool()
    Move = pool.get('stock.move')
    Date = pool.get('ir.date')

    Move.do([m for s in shipments for m in s.moves])
    for company, c_shipments in groupby(
            shipments, key=lambda s: s.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        cls.write([s for s in c_shipments if not s.effective_date], {
                'effective_date': today,
                })

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments for m in s.moves])

def assign_try(cls, shipments, with_childs=None):
    pool = Pool()
    Move = pool.get('stock.move')
    shipments = [s for s in shipments if s.state == 'waiting']
    to_assign = defaultdict(list)
    for shipment in shipments:
        location_type = shipment.from_location.type
        for move in shipment.assign_moves:
            if move.assignation_required:
                to_assign[location_type].append(move)
    success = True
    for location_type, moves in to_assign.items():
        if with_childs is None:
            _with_childs = location_type == 'view'
        elif not with_childs and location_type == 'view':
            _with_childs = True
        else:
            _with_childs = with_childs
        if not Move.assign_try(moves, with_childs=_with_childs):
            success = False
    if success:
        cls.assign(shipments)
    else:
        with cls.bulk_func('assign', auto=False) as assign:
            for shipment in shipments:
                if any(
                        m.state in {'staging', 'draft'}
                        for m in shipment.assign_moves
                        if m.assignation_required):
                    continue
                assign.push(shipment)

def _get_reschedule_domain(cls, date):
    return [
        ('state', 'in', ['waiting', 'assigned']),
        ('planned_date', '<', date),
        ]

def on_change_warehouse(self):
    if self.warehouse:
        if self.warehouse.picking_location:
            self.warehouse_storage = self.warehouse.picking_location
        else:
            self.warehouse_storage = self.warehouse.storage_location
        self.warehouse_output = self.warehouse.output_location
    else:
        self.warehouse_storage = self.warehouse_output = None

def get_outgoing_moves(self, name):
    if self.warehouse_output == self.warehouse_storage:
        moves = self.moves
    else:
        moves = filter(
            lambda m: m.from_location == self.warehouse_output, self.moves)
    return sort(moves, self.__class__.outgoing_moves.order)

def set_outgoing_moves(cls, shipments, name, value):
    if not value:
        return
    cls.write(shipments, {
            'moves': value,
            })

def get_inventory_moves(self, name):
    moves = filter(
        lambda m: m.to_location == self.warehouse_output, self.moves)
    return sort(moves, self.__class__.inventory_moves.order)

def set_inventory_moves(cls, shipments, name, value):
    if not value:
        return
    cls.write(shipments, {
            'moves': value,
            })

def get_origins(self, name):
    return ', '.join(set(filter(None,
                (m.origin_name for m in self.outgoing_moves))))

def chat_language(self, audience='internal'):
    language = super().chat_language(audience=audience)
    if audience == 'public':
        language = self.customer.lang.code if self.customer.lang else None
    return language

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.outgoing_moves
            if m.state != 'staging'])
    Move.delete([m for s in shipments for m in s.inventory_moves
            if m.state in {'staging', 'draft', 'cancelled'}])

def wait(cls, shipments, moves=None):
    """
    Complete inventory moves to match the products and quantities
    that are in the outgoing moves.
    If moves is set, only this subset is set to draft.
    """
    Move = Pool().get('stock.move')

    if moves is None:
        moves = sum((s.inventory_moves for s in shipments), ())
    else:
        assert all(m.shipment in shipments for m in moves)
    Move.draft(moves)
    with Move.bulk_delete(auto=False) as delete:
        for shipment in shipments:
            for move in shipment.inventory_moves:
                if move.state in {'draft', 'cancelled'}:
                    delete.push(move)
    Move.draft([
            m for s in shipments for m in s.outgoing_moves
            if m.state != 'staging'])

    with Move.bulk_save(auto=False) as save:
        for shipment in shipments:
            if shipment.warehouse_storage == shipment.warehouse_output:
                # Do not create inventory moves
                continue
            for move in shipment.outgoing_moves:
                if move.state in {'cancelled', 'done'}:
                    continue
                if inventory_move := shipment._get_inventory_move(move):
                    save.push(inventory_move)
    cls.set_number(shipments)

def pack(cls, shipments):
    pool = Pool()
    Move = pool.get('stock.move')
    with Move.bulk_delete() as delete:
        outgoing_moves = []
        for shipment in shipments:
            for move in shipment.inventory_moves:
                if move.state not in {'done', 'cancelled'}:
                    raise AccessError(
                        gettext('stock.msg_shipment_pack_inventory_done',
                            shipment=shipment.rec_name))
